use std::collections::HashMap
use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if p.len() == 0 {
            continue
        }
        let cmd = p[0]
        if cmd == "open" && p.len() >= 3 {
            let amt: int = p[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(p[1]) {
                println("error: duplicate account")
            } else {
                acc.insert(p[1], amt)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && p.len() >= 3 {
            let amt: int = p[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                let bal: int = acc[p[1]]
                if cmd == "deposit" {
                    acc.insert(p[1], bal + amt)
                    println("ok")
                } else if bal < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(p[1], bal - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && p.len() >= 4 {
            let amt: int = p[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else if !acc.contains_key(p[2]) {
                println("error: unknown account ${p[2]}")
            } else if p[1] == p[2] {
                println("error: same account")
            } else {
                let fb: int = acc[p[1]]
                let tb: int = acc[p[2]]
                if fb < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(p[1], fb - amt)
                    acc.insert(p[2], tb + amt)
                    println("ok")
                }
            }
        } else if cmd == "balance" && p.len() >= 2 {
            if !acc.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                let b: int = acc[p[1]]
                println("${b}")
            }
        }
    }
    let mut keys: Vec<string> = acc.keys().collect()
    keys.sort()
    for k in keys {
        let b: int = acc[k]
        println("${k} ${b}")
    }
}

